CREATE TABLE IF NOT EXISTS user_profiles (user_id TEXT PRIMARY KEY, school_id UUID REFERENCES schools(id) ON DELETE CASCADE, full_name TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'parent' CHECK (role IN ('super_admin','school_admin','principal','teacher','accountant','student','parent','librarian')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS classes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, name TEXT NOT NULL, arm TEXT NOT NULL DEFAULT 'A', capacity INTEGER NOT NULL DEFAULT 40, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(school_id,name,arm));
CREATE TABLE IF NOT EXISTS students (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, admission_no TEXT NOT NULL, first_name TEXT NOT NULL, last_name TEXT NOT NULL, gender TEXT, date_of_birth DATE, email TEXT, phone TEXT, parent_name TEXT, parent_phone TEXT, address TEXT, class_id UUID REFERENCES classes(id), status TEXT NOT NULL DEFAULT 'active', admitted_on DATE DEFAULT CURRENT_DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(school_id,admission_no));
CREATE TABLE IF NOT EXISTS staff (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, full_name TEXT NOT NULL, email TEXT, phone TEXT, role TEXT NOT NULL DEFAULT 'teacher', department TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS academic_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, name TEXT NOT NULL, start_date DATE, end_date DATE, is_current BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS subjects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, name TEXT NOT NULL, code TEXT, class_id UUID REFERENCES classes(id), teacher_id UUID REFERENCES staff(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());